// Árvore Projeto › Seção › Tarefa › Subtarefa (sem IA) com ids curtos + prompt. Ordem do prompt: do mais estável ao mais volátil
// (regras → exemplos → árvore → data/hora; a mensagem vai em role:user) para aproveitar o cache de prefixo do DeepSeek.
const BUDGET = 12000;      // caracteres da árvore (~3.000 tokens)
const TITLE_LEN = 60;
const squash = (v) => String(v || '').replace(/\s+/g, ' ').trim();
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const STOP = new Set(['de', 'da', 'do', 'das', 'dos', 'a', 'o', 'as', 'os', 'e', 'em', 'no', 'na', 'para', 'pra', 'com', 'um', 'uma']);
const words = (s) => norm(s).split(' ').filter((w) => w.length > 2 && !STOP.has(w));

const msg = $('Recebe update').first().json;
// Agendas do Google Calendar (buscadas antes das do Todoist; se falhar, segue sem agendas)
const calRes = $('Google: listar agendas').first().json || {};
const calendars = (Array.isArray(calRes.items) ? calRes.items : [])
  .filter((c) => !c.deleted && !c.hidden)
  .map((c) => ({ id: c.id, name: squash(c.summaryOverride || c.summary), desc: squash(c.description), primary: !!c.primary }))
  .filter((c) => c.name);
const calendarsError = calRes.error ? String(calRes.error.message || calRes.error).slice(0, 160) : null;
const calendarLines = calendars.length
  ? calendars.map((c) => '- ' + c.name + (c.primary ? ' (principal)' : '') + (c.desc ? ': ' + cut(c.desc, 160) : ''))
  : ['(nenhuma agenda disponível — use "calendar": null)'];
const rawProjects = ($('Buscar projetos Todoist').first().json.results || []).filter((p) => !p.is_archived && !p.is_deleted);
const rawSections = ($('Buscar seções Todoist').first().json.results || []).filter((s) => !s.is_archived && !s.is_deleted);
let tasksError = null;
const rawTasks = [];
for (const it of $input.all()) {
  if (it.json.error) { tasksError = String(it.json.error.message || it.json.error).slice(0, 160); continue; }
  for (const t of (it.json.results || [])) if (!t.checked && !t.is_deleted) rawTasks.push(t);
}

const byOrder = (a, b) => (a.child_order || 0) - (b.child_order || 0);
const projects = [...rawProjects].sort((a, b) => (b.inbox_project ? 1 : 0) - (a.inbox_project ? 1 : 0) || byOrder(a, b));
const taskById = new Map(rawTasks.map((t) => [t.id, t]));
const kids = new Map();
const roots = [];
for (const t of [...rawTasks].sort(byOrder)) {
  if (t.parent_id && taskById.has(t.parent_id)) { if (!kids.has(t.parent_id)) kids.set(t.parent_id, []); kids.get(t.parent_id).push(t); } else roots.push(t);
}
const depthById = {};
const descendants = {};
(function walk(list, depth) {
  for (const t of list) { depthById[t.id] = depth; const c = kids.get(t.id) || []; walk(c, depth + 1); descendants[t.id] = c.reduce((a, k) => a + 1 + descendants[k.id], 0); }
})(roots, 1);

const msgWords = new Set(words(msg.text));
const matches = (t) => words(t.content).some((w) => msgWords.has(w));
const keepIds = new Set(); // nível 3: só tarefas com filhos, que casam com a mensagem, e seus ancestrais
for (const t of rawTasks) {
  if (kids.has(t.id) || matches(t)) { for (let x = t; x; x = x.parent_id ? taskById.get(x.parent_id) : null) keepIds.add(x.id); }
}

function render(level) {
  const maxDepth = level >= 1 ? 2 : Infinity;
  const titleLen = level >= 2 ? 35 : TITLE_LEN;
  const onlyKept = level >= 3;
  const idmap = { P: {}, S: {}, T: {} };
  const lines = [];
  let np = 0; let ns = 0; let nt = 0;
  const pathOf = (parts) => parts.join(' › ');
  const emitTasks = (list, indent, depth, base, pcode, scode, parentCode, omitted) => {
    for (const t of list) {
      if (onlyKept && !keepIds.has(t.id)) { omitted.n++; continue; }
      const code = 'T' + (++nt);
      const title = cut(squash(t.content), titleLen);
      const path = base.concat(cut(squash(t.content), 40));
      idmap.T[code] = { id: t.id, content: squash(t.content), project: pcode, section: scode, parent: parentCode, depth, path: pathOf(path) };
      const sub = kids.get(t.id) || [];
      const hide = depth >= maxDepth && sub.length;
      lines.push({ kind: 'T', text: ' '.repeat(indent) + code + ' ' + title + (hide ? ' (+' + descendants[t.id] + ' subtarefas)' : '') });
      if (!hide) emitTasks(sub, indent + 2, depth + 1, path, pcode, scode, code, omitted);
    }
  };
  for (const p of projects) {
    const pcode = 'P' + (++np);
    const name = p.inbox_project ? 'Entrada' : squash(p.name);
    idmap.P[pcode] = { id: p.id, name, inbox: !!p.inbox_project };
    const desc = squash(p.description);
    lines.push({ kind: 'P', text: pcode + ' ' + name + (p.inbox_project ? ' (inbox)' : '') + (desc ? ': ' + cut(desc, 200) : '') });
    const omitted = { n: 0 };
    const own = roots.filter((t) => t.project_id === p.id);
    emitTasks(own.filter((t) => !t.section_id || !rawSections.some((s) => s.id === t.section_id)), 2, 1, [name], pcode, null, null, omitted);
    for (const s of rawSections.filter((x) => x.project_id === p.id).sort(byOrder)) {
      const scode = 'S' + (++ns);
      idmap.S[scode] = { id: s.id, name: squash(s.name), project: pcode };
      const sdesc = squash(s.description);
      lines.push({ kind: 'S', text: '  ' + scode + ' ' + squash(s.name) + (sdesc ? ': ' + cut(sdesc, 200) : '') });
      emitTasks(own.filter((t) => t.section_id === s.id), 4, 1, [name, squash(s.name)], pcode, scode, null, omitted);
    }
    if (omitted.n) lines.push({ kind: 'T', text: '  (+' + omitted.n + ' tarefas omitidas)' });
  }
  return { idmap, lines, tasks: nt };
}

let level = 0;
let r = render(0);
let size = () => r.lines.map((l) => l.text).join('\n').length;
while (size() > BUDGET && level < 3) { level++; r = render(level); }
if (size() > BUDGET) { // último recurso: corta linhas de tarefa do fim (mantém projetos e seções)
  let total = size();
  for (let i = r.lines.length - 1; i >= 0 && total > BUDGET; i--) {
    if (r.lines[i].kind === 'T') { total -= r.lines[i].text.length + 1; r.lines.splice(i, 1); }
  }
  level = 4;
}
const tree = r.lines.map((l) => l.text).join('\n');
const idmap = r.idmap;
const tById = {};
for (const [code, t] of Object.entries(idmap.T)) tById[t.id] = code;

// Fuso e idioma configuráveis no .env (CHRONOS_TIMEZONE / CHRONOS_LOCALE)
const TZ = $env.CHRONOS_TIMEZONE || 'America/Sao_Paulo';
const LOCALE = $env.CHRONOS_LOCALE || 'pt-BR';
const now = $now.setZone(TZ).setLocale(LOCALE);
const system = [
  'Você é o Chronos, um assistente de produtividade pessoal. Leia a mensagem INTEIRA do usuário e responda SOMENTE com um objeto JSON válido, sem texto extra, exatamente neste formato:',
  '{"type": "evento" | "tarefa", "title": "string", "description": "string", "priority": 1 | 2 | 3 | 4, "due": "string ou null", "destino": {"projeto": "P#", "secao": "S# ou null", "pai": "T# ou null"}, "eh_subtarefa": true | false, "pai_citado": "string ou null", "candidatos_pai": ["T#"], "subtarefas": [{"title": "string", "due": "string ou null"}], "start": "string ou null", "end": "string ou null", "location": "string ou null", "calendar": "string ou null"}',
  '',
  'Regras:',
  '- "type" — decida entre "evento" e "tarefa" NESTA ordem:',
  '  1) Intenção explícita vence: se o usuário escreveu "tarefa", "Tarefa:", "todoist", "lembrete", "anotar", "criar", "colocar na lista" ou pediu algo para ser feito, é "tarefa". Só é "evento" se ele escreveu "evento", "compromisso", "agendar" ou "na agenda".',
  '  2) Horário NÃO torna algo um evento: "entregar o relatório às 17h" ou "ligar para o banco 10h" são tarefas com prazo (campo "due").',
  '  3) "evento" SOMENTE quando a mensagem tiver uma pista clara de algo que ACONTECE em data/hora marcada: reunião, daily, call, consulta, aula, aniversário, festa, casamento, viagem, show, almoço/jantar, encontro, ou as palavras "evento"/"agendar". Sem essa pista, é "tarefa": uma ação a EXECUTAR ou um item a lembrar, mesmo que cite data ou hora (ex.: nome de curso, prova, certificação, entrega, ligação, conversa).',
  '  4) Na dúvida, escolha "tarefa": uma tarefa sempre fica registrada no Todoist, enquanto um evento errado polui a agenda.',
  '- "title": título CURTO e objetivo, com no máximo 6 palavras. Para tarefa, no imperativo ("Comprar leite", "Revisar contrato X"); para evento, o nome do compromisso ("Dentista", "Reunião de planejamento"). Nunca coloque no título data, hora, prazo, local, prioridade ou detalhes — eles vão nos outros campos.',
  '- "description": vale para tarefa E para evento. Contexto útil que não coube no título (detalhes, motivo, quantidades, pessoas, referências, links), em português claro. Não repita data, hora ou local (já têm campos próprios) nem os passos que forem para "subtarefas". Se não houver nada além do título (ex.: "comprar pão"), devolva "" — nunca copie o título na descrição. Texto longo SEM passos distintos: título curto + descrição.',
  '- "priority": 1 = urgente, 2 = alta, 3 = média, 4 = normal. Use 4 quando não houver indício de urgência.',
  '- "due": o prazo mencionado, em linguagem natural em português (ex.: "amanhã", "sexta às 15h", "dia 20"), ou null se nenhum prazo foi citado.',
  '',
  'Onde a tarefa entra (use SOMENTE ids da árvore abaixo; nunca invente ids):',
  '- "destino.projeto": o id P# do projeto, usando a descrição de cada projeto e seção para decidir. Se nenhum se aplicar claramente, o projeto da Entrada (inbox). "destino.secao": o id S# de uma seção DESSE projeto que combine claramente com a tarefa, ou null.',
  '- "destino.pai": o id T# da tarefa existente da qual esta é subtarefa — SÓ com alta certeza. Itens de uma lista que já existe na árvore (ex.: um item de compra e uma tarefa "Lista de Compras") entram como subtarefa dela. Se não existe tarefa-pai plausível, é uma tarefa normal: "eh_subtarefa": false e "pai": null.',
  '- Se houver DUAS OU MAIS tarefas plausíveis como pai, deixe "pai": null, "eh_subtarefa": true e liste de 2 a 5 ids em "candidatos_pai". Fora dessa dúvida, "candidatos_pai": [].',
  '- Citação explícita ("subtarefa de X", "dentro de X", "parte de X", "etapa de X", "na tarefa X"): "eh_subtarefa": true e resolva X para um id da árvore. Se X não existir na árvore, "pai": null, "candidatos_pai": [] e "pai_citado" com o texto de X exatamente como o usuário escreveu. "pai_citado" é null quando o usuário não citou a tarefa-pai.',
  '- "subtarefas": só para tarefa. Quando o texto tiver DUAS OU MAIS ações distintas e executáveis separadamente, cada passo vira {"title": título curto no imperativo, "due": prazo próprio ou null} (no máximo 10); o "title" principal nomeia o objetivo geral (ex.: "Fazer a obra") e NUNCA repete o título de uma subtarefa; a "description" fica só com o contexto. Sem passos distintos, "subtarefas": []. Se a mensagem mistura ações de assuntos diferentes (ex.: um item de compra e um recado de correio), NÃO a coloque dentro de uma lista existente: é uma tarefa nova com esses passos em "subtarefas". Só use um pai existente quando TODA a mensagem for item ou etapa dele.',
  '',
  'Campos exclusivos de evento (para tarefa, devolva null em start/end/location/calendar; para evento, "destino.projeto" é o projeto da Entrada, "pai" null, "eh_subtarefa" false e "subtarefas" []):',
  '- "start": início do evento como data ABSOLUTA, calculada a partir da data e hora atual informada abaixo, no formato "YYYY-MM-DDTHH:mm" (ou "YYYY-MM-DD" se nenhum horário foi citado). null se nenhuma data foi citada. "amanhã", "sexta", "dia 20" devem virar a data real.',
  '- "end": término do evento no mesmo formato, ou null se não foi informado (o sistema assume 1 hora de duração).',
  '- "location": o local citado (endereço, sala, estabelecimento, cidade ou link), ou null.',
  '- "calendar": a agenda do evento, EXATAMENTE um dos nomes da lista "AGENDAS DO GOOGLE CALENDAR" abaixo (use a descrição de cada agenda para decidir), ou null se nenhuma combinar claramente.',
  '',
  'AGENDAS DOS EXEMPLOS (fictícias, só para os exemplos abaixo): "Trabalho", "Pessoal".',
  'ÁRVORE DOS EXEMPLOS (fictícia, só para os exemplos abaixo — a árvore real vem depois):',
  'P1 Entrada (inbox)',
  '  T1 Lista de Compras',
  '  T2 Compras da obra',
  'P2 Casa: manutenção e organização da casa',
  '  T3 Montar estante',
  '  S1 Festas: aniversários e confraternizações',
  'P3 Estudos: cursos e leituras',
  '  S2 Leitura: livros e artigos',
  '',
  'EXEMPLO DE ENTRADA: "comprar leite amanhã"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Comprar leite","description":"","priority":4,"due":"amanhã","destino":{"projeto":"P1","secao":null,"pai":"T1"},"eh_subtarefa":true,"pai_citado":null,"candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "ler o capítulo 5 do livro de Estatística até sexta"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Ler capítulo 5 de Estatística","description":"","priority":3,"due":"sexta","destino":{"projeto":"P3","secao":"S2","pai":null},"eh_subtarefa":false,"pai_citado":null,"candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "preciso organizar o aniversário do João no sábado: reservar o salão do prédio, mandar os convites no grupo da família e encomendar o bolo com a Maria (de chocolate, pra 30 pessoas)"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Organizar aniversário do João","description":"Festa para 30 pessoas; bolo de chocolate.","priority":3,"due":"sábado","destino":{"projeto":"P2","secao":"S1","pai":null},"eh_subtarefa":false,"pai_citado":null,"candidatos_pai":[],"subtarefas":[{"title":"Reservar o salão do prédio","due":null},{"title":"Mandar os convites no grupo da família","due":null},{"title":"Encomendar o bolo com a Maria","due":null}],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "Comprar parafusos, subtarefa de Montar estante"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Comprar parafusos","description":"","priority":4,"due":null,"destino":{"projeto":"P2","secao":null,"pai":"T3"},"eh_subtarefa":true,"pai_citado":"Montar estante","candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "Anotar as medidas, etapa de Reforma da garagem"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Anotar as medidas","description":"","priority":4,"due":null,"destino":{"projeto":"P1","secao":null,"pai":null},"eh_subtarefa":true,"pai_citado":"Reforma da garagem","candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "comprar cimento"',
  'EXEMPLO DE SAÍDA JSON (T1 e T2 são listas de compra plausíveis): {"type":"tarefa","title":"Comprar cimento","description":"","priority":4,"due":null,"destino":{"projeto":"P1","secao":null,"pai":null},"eh_subtarefa":true,"pai_citado":null,"candidatos_pai":["T1","T2"],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "Tarefa: ligar para o Carlos às 12h sobre o orçamento"',
  'EXEMPLO DE SAÍDA JSON (horário em tarefa é prazo, não evento): {"type":"tarefa","title":"Ligar para o Carlos","description":"Assunto: orçamento.","priority":4,"due":"hoje às 12h","destino":{"projeto":"P1","secao":null,"pai":null},"eh_subtarefa":false,"pai_citado":null,"candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "Coloque a tarefa abaixo no Todoist\n\nRevisar a proposta do cliente hoje 18h"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Revisar proposta do cliente","description":"","priority":4,"due":"hoje às 18h","destino":{"projeto":"P1","secao":null,"pai":null},"eh_subtarefa":false,"pai_citado":null,"candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA: "entregar o relatório mensal às 17h"',
  'EXEMPLO DE SAÍDA JSON: {"type":"tarefa","title":"Entregar relatório mensal","description":"","priority":3,"due":"hoje às 17h","destino":{"projeto":"P1","secao":null,"pai":null},"eh_subtarefa":false,"pai_citado":null,"candidatos_pai":[],"subtarefas":[],"start":null,"end":null,"location":null,"calendar":null}',
  '',
  'EXEMPLO DE ENTRADA (supondo hoje = segunda-feira, 14/09/2026): "reunião com o time quinta às 14h na sala 3 pra fechar o cronograma do lançamento"',
